#!/usr/bin/env node
/**
 * Grades the SQL reader on PL/SQL against the ANTLR project's PL/SQL grammar.
 *
 * The parser that is not ours: grammars-v4's `sql/plsql` grammar at a pinned
 * commit, generated by the ANTLR 4.13.2 tool and compiled with the machine's
 * Java, around `PlSqlEmitter.java` beside this file. The tool jar and the
 * grammar are fetched once into a cache folder of this tool's own,
 * `~/.cache/live-documentation/oracle-plsql`, and checked against the SHA-256
 * sums written below; the parser is generated and compiled in a scratch folder
 * each run. Without `java` and `javac` on the path it says so in one line and
 * exits; it installs nothing.
 *
 * Every PL/SQL file of the folder (`.sql`, `.pks`, `.pkb`, `.tps`, `.tpb`,
 * `.syn`, `.pck`, `.pkg`, `.trg`) is copied into the scratch folder with
 * `.sql` added to its name, since the reader reads `.sql`, and with every
 * SQL*Plus line blanked, its line kept (`PROMPT`, `REM`, `SET`, `SPOOL`,
 * `DEFINE`, `@script`, `EXEC` and the like): the grammar does not read
 * SQL*Plus, and both readers are given the same text. Calls on `EXEC` lines
 * are therefore on neither side.
 *
 * What this oracle cannot judge:
 *   - names: the grammar does not resolve them. It cannot tell a package's
 *     member from a schema's function, a collection's element `arr(i)` from a
 *     call, or a package's own procedure called by one part from a standalone
 *     one. Calls are graded only when written with two or more parts; calls by
 *     one part are counted. A name is resolved here by a presumption written
 *     in this file, as the T-SQL comparison's is: a call `a.b(…)` uses package
 *     or type `a` when the folder creates one, else the object `a.b`; a table's
 *     name its schema and table, or the table alone;
 *   - what the grammar refuses: on utPLSQL (develop, 2026-11-19) 98 of 366
 *     files, among them every `create noneditionable synonym`, type attributes
 *     written `integer default`, `(self as …)` in type bodies and several core
 *     package bodies. A refused file is listed and not graded, and the objects
 *     it creates are in neither side's index.
 *
 * It prints figures: objects by kind (packages, types, sequences and the
 * rest included, the kinds the reader has no symbol for), lines right,
 * dependency lines right, missing and invented by how each is used, what is
 * counted and not graded, and how many names the reader keeps today an
 * object of a kind it has no symbol for would turn into links.
 *
 * Usage:
 *   npm run oracle:plsql -- <folder> [--json] [--detail]
 */
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import * as fs from "node:fs";
import os from "node:os";
import path from "node:path";
import process from "node:process";

import { sqlAdapter } from "@live-documentation/engine/live-docs/adapters/sql";
import type { WorkspaceSymbolIndex } from "@live-documentation/engine/live-docs/coreTypes";

/** The grammars-v4 commit the grammar is read at: the last change to `sql/plsql` as of 2026-11-19. */
export const GRAMMAR_COMMIT = "de38599628d221099c046e92962f70204d852b54";
const GRAMMAR_URL = `https://raw.githubusercontent.com/antlr/grammars-v4/${GRAMMAR_COMMIT}/sql/plsql`;
const ANTLR = { url: "https://repo1.maven.org/maven2/org/antlr/antlr4/4.13.2/antlr4-4.13.2-complete.jar", file: "antlr-4.13.2-complete.jar", sha256: "eae2dfa119a64327444672aff63e9ec35a20180dc5b8090b7a6ab85125df4d76" };
const GRAMMAR = [
  { path: "PlSqlLexer.g4",             sha256: "aaddaa2f9d40e10ab71e83a402499ae893aa7f03497a631e5c12f2c4cd1d2567" },
  { path: "PlSqlParser.g4",            sha256: "eb276be3890a9d9a92d7a654300fd717cb2db4800ab35fe92326b55e784bf770" },
  { path: "Java/PlSqlLexerBase.java",  sha256: "88e8c740cf204eb4c5f509b395435a2ca8608dfcdade5372afa818944e50b5ce" },
  { path: "Java/PlSqlParserBase.java", sha256: "f33d462f26313550b3c6df2994ba6e88345e95b015fc607055cb9edb658f17fa" }
];
const CACHE = path.join(os.homedir(), ".cache", "live-documentation", "oracle-plsql");

const SUFFIXES = new Set([".sql", ".pks", ".pkb", ".tps", ".tpb", ".syn", ".pck", ".pkg", ".trg"]);
/** A SQL*Plus line: a command SQL*Plus runs itself, never sent to the database as SQL. */
export const SQLPLUS_LINE = /^\s*(PROMPT|PRO|REM|REMARK|SET|SPOOL|WHENEVER|EXIT|QUIT|DEFINE|DEF|UNDEFINE|COLUMN|COL|SHOW|VARIABLE|VAR|PRINT|EXEC|EXECUTE|CONNECT|CONN|TIMING|HOST|ACCEPT|PAUSE|CLEAR|TTITLE|BTITLE|BREAK|COMPUTE|@{1,2}\S*)(\s|$)/iu;

/** A text with every SQL*Plus line blanked, each line kept, so that lines still count. */
export function withoutSqlPlus(text: string): string {
  return text.split("\n").map((line) => (SQLPLUS_LINE.test(line) ? (line.endsWith("\r") ? "\r" : "") : line)).join("\n");
}

async function fetched(url: string, file: string, sha256: string): Promise<string> {
  const target = path.join(CACHE, file);
  if (!fs.existsSync(target)) {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`could not fetch ${url}: ${response.status}`);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, Buffer.from(await response.arrayBuffer()));
  }
  const sum = createHash("sha256").update(fs.readFileSync(target)).digest("hex");
  if (sum !== sha256) throw new Error(`${target} has SHA-256 ${sum}, not ${sha256}; remove it and run again`);
  return target;
}

function run(command: string, args: string[], options: { cwd?: string; input?: string } = {}): string {
  const result = spawnSync(command, args, { encoding: "utf8", maxBuffer: 1024 * 1024 * 1024, ...options });
  if (result.error || result.status !== 0) throw new Error(`${command} ${args.slice(0, 3).join(" ")} failed: ${result.error?.message ?? result.stderr}`);
  return result.stdout;
}

interface Create { kind: string; name: string; line: number; in?: string }
interface Reference { how: string; name: string; line: number }
interface Facts { parseErrors: Array<{ line: number; message: string }>; creates: Create[]; references: Reference[] }

/** Builds the parser in a scratch folder and runs it over the prepared files. */
async function parse(work: string, files: string[]): Promise<Record<string, Facts>> {
  const jar = await fetched(ANTLR.url, ANTLR.file, ANTLR.sha256);
  const build = path.join(work, "parser");
  fs.mkdirSync(build, { recursive: true });
  for (const file of GRAMMAR) fs.copyFileSync(await fetched(`${GRAMMAR_URL}/${file.path}`, `${GRAMMAR_COMMIT}/${path.basename(file.path)}`, file.sha256), path.join(build, path.basename(file.path)));
  fs.copyFileSync(path.join(__dirname, "PlSqlEmitter.java"), path.join(build, "PlSqlEmitter.java"));
  run("java", ["-jar", jar, "-Dlanguage=Java", "-no-listener", "PlSqlLexer.g4", "PlSqlParser.g4"], { cwd: build });
  const classes = path.join(work, "classes");
  run("javac", ["-J-Xmx4g", "-nowarn", "-cp", jar, "-d", classes, ...fs.readdirSync(build).filter((f) => f.endsWith(".java"))], { cwd: build });
  const printed = run("java", ["-Xss64m", "-Xmx6g", "-cp", `${jar}${path.delimiter}${classes}`, "PlSqlEmitter", path.join(work, "files")], { input: files.join("\n") });
  return (JSON.parse(printed) as { files: Record<string, Facts> }).files;
}

/** Copies a folder's PL/SQL files into `work/files` with `.sql` names and SQL*Plus blanked; returns their names there. */
function prepare(folder: string, work: string): string[] {
  const walk = (dir: string): string[] => fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => (entry.isDirectory() ? (["node_modules", ".git", ".live-documentation"].includes(entry.name) ? [] : walk(path.join(dir, entry.name))) : [path.join(dir, entry.name)]));
  const files: string[] = [];
  for (const file of walk(folder)) {
    const suffix = path.extname(file).toLowerCase();
    if (!SUFFIXES.has(suffix)) continue;
    const relative = path.relative(folder, file).split(path.sep).join("/") + (suffix === ".sql" ? "" : ".sql");
    fs.mkdirSync(path.dirname(path.join(work, "files", relative)), { recursive: true });
    fs.writeFileSync(path.join(work, "files", relative), withoutSqlPlus(fs.readFileSync(file, "utf8")));
    files.push(relative);
  }
  return files.sort();
}

const OBJECT_KINDS = new Set(["package", "procedure", "function", "view", "table", "trigger", "type", "synonym", "sequence"]);
const ADAPTER_KIND: Record<string, string> = { procedure: "procedure", function: "sql-function", view: "view", table: "table" };
const GRADED = new Set(["select", "insert", "update", "delete", "merge", "foreign-key", "execute", "call"]);

/** Grades the adapter's reading of the prepared files against the parser's record. */
export async function gradePlSql(root: string, record: Record<string, Facts>) {
  const graded = Object.keys(record).filter((file) => record[file].parseErrors.length === 0).sort();
  const fold = (name: string) => name.toLowerCase().split(".");
  const objects: Array<Create & { file: string; parts: string[] }> = [];
  for (const file of graded) for (const create of record[file].creates) if (OBJECT_KINDS.has(create.kind)) objects.push({ ...create, file, parts: fold(create.name) });
  const byLast = new Map<string, typeof objects>();
  for (const object of objects) byLast.set(object.parts.at(-1)!, [...(byLast.get(object.parts.at(-1)!) ?? []), object]);
  const targets = (how: string, parts: string[]) => {
    const called = how === "call" || how === "execute";
    if (called && parts.length >= 2) {
      const holders = (byLast.get(parts.length >= 3 ? parts.at(-2)! : parts[0]) ?? []).filter((object) => object.kind === "package" || object.kind === "type");
      if (holders.length > 0) return holders;
    }
    return (byLast.get(parts.at(-1)!) ?? []).filter((object) => (parts.length < 2 || object.parts.length < 2 || object.parts.at(-2) === parts.at(-2)) && !(called && (object.kind === "table" || object.kind === "view")));
  };

  const symbols = new Map<string, Array<{ name: string; kind: string; line?: number }>>();
  for (const file of graded) symbols.set(file, ((await sqlAdapter.analyze({ absolutePath: path.join(root, file), workspaceRoot: root }))?.symbols ?? []).map((symbol) => ({ name: symbol.name, kind: symbol.kind, line: symbol.location?.line })));
  const index: WorkspaceSymbolIndex = new Map();
  for (const [file, list] of symbols) for (const symbol of list) index.set(symbol.name, [...(index.get(symbol.name) ?? []), { liveDocPath: "", sourcePath: file, anchor: "", kind: symbol.kind }]);

  const kinds: Record<string, { expected: number; found: number; linesRight: number }> = {};
  const missingObjects: string[] = [];
  const inventedObjects: string[] = [];
  const dependency = { expected: 0, right: 0, missing: [] as string[], invented: [] as string[], byHow: {} as Record<string, { expected: number; right: number }> };
  const ungraded: Record<string, number> = {};
  const wouldResolve: Record<string, number> = {};
  for (const file of graded) {
    const mine = [...(symbols.get(file) ?? [])];
    for (const create of record[file].creates.filter((candidate) => OBJECT_KINDS.has(candidate.kind))) {
      const bucket = (kinds[create.kind] ??= { expected: 0, found: 0, linesRight: 0 });
      bucket.expected += 1;
      const at = mine.findIndex((symbol) => symbol.kind === ADAPTER_KIND[create.kind] && symbol.name.toLowerCase() === create.name.toLowerCase());
      if (at === -1) { missingObjects.push(`${file}:${create.line} ${create.kind} ${create.name}`); continue; }
      bucket.found += 1;
      if (mine[at].line === create.line) bucket.linesRight += 1;
      mine.splice(at, 1);
    }
    inventedObjects.push(...mine.map((symbol) => `${file}:${symbol.line} ${symbol.kind} ${symbol.name}`));

    const own  = record[file].creates.map((create) => fold(create.name));
    const want = new Map<string, Set<string>>();
    for (const reference of record[file].references) {
      const parts = fold(reference.name);
      if (!GRADED.has(reference.how)) { ungraded[reference.how] = (ungraded[reference.how] ?? 0) + 1; continue; }
      if ((reference.how === "call" || reference.how === "execute") && parts.length < 2) { ungraded[`${reference.how} by one part`] = (ungraded[`${reference.how} by one part`] ?? 0) + 1; continue; }
      if (parts.length >= 2 && parts.at(-2) === "sys") continue;
      const hits = targets(reference.how, parts).filter((object) => object.file !== file);
      const made = hits.length > 0 ? hits.map((object) => `-> ${object.file} :: ${object.name.toLowerCase()}`)
        : own.some((created) => created.at(-1) === parts.at(-1) || created.at(-1) === parts[0]) ? [] : [`= ${reference.name.toLowerCase()}`];
      for (const line of made) want.set(line, (want.get(line) ?? new Set<string>()).add(reference.how));
    }
    const have = new Set<string>();
    for (const entry of (await sqlAdapter.analyze({ absolutePath: path.join(root, file), workspaceRoot: root, symbolIndex: index }))?.dependencies ?? []) {
      if (entry.resolvedPath) for (const symbol of entry.symbols) have.add(`-> ${entry.resolvedPath} :: ${symbol.toLowerCase()}`);
      else have.add(`= ${entry.specifier.toLowerCase()}`);
    }
    for (const [line, hows] of want) {
      const right = have.has(line);
      dependency.expected += 1;
      if (right) dependency.right += 1; else dependency.missing.push(`${file}: ${line}`);
      for (const how of hows) { const bucket = (dependency.byHow[how] ??= { expected: 0, right: 0 }); bucket.expected += 1; if (right) bucket.right += 1; }
    }
    for (const line of have) {
      if (!want.has(line)) dependency.invented.push(`${file}: ${line}`);
      if (!line.startsWith("= ")) continue;
      const parts = line.slice(2).split(".");
      const kind = [...targets("call", parts), ...targets("select", parts)].find((object) => !ADAPTER_KIND[object.kind])?.kind;
      if (kind) wouldResolve[kind] = (wouldResolve[kind] ?? 0) + 1;
    }
  }
  const members: Record<string, number> = {};
  for (const file of graded) for (const create of record[file].creates) if (!OBJECT_KINDS.has(create.kind)) members[create.kind] = (members[create.kind] ?? 0) + 1;
  return {
    files: { read: Object.keys(record).length, graded: graded.length, refused: Object.keys(record).filter((file) => record[file].parseErrors.length > 0).map((file) => `${file}:${record[file].parseErrors[0].line} ${record[file].parseErrors[0].message}`) },
    objects: { kinds, members, missing: missingObjects, invented: inventedObjects },
    dependency,
    ungraded,
    wouldResolve
  };
}

async function main(): Promise<void> {
  const args   = process.argv.slice(2);
  const folder = args.find((arg) => !arg.startsWith("--"));
  if (!folder) {
    console.log("Usage: npm run oracle:plsql -- <folder> [--json] [--detail]");
    process.exit(1);
  }
  for (const tool of ["java", "javac"]) {
    if (spawnSync(tool, ["-version"], { encoding: "utf8" }).error) {
      console.log(`oracle:plsql needs ${tool} on the path, to build the ANTLR PL/SQL parser; it installs nothing.`);
      process.exit(1);
    }
  }
  const work = fs.mkdtempSync(path.join(os.tmpdir(), "oracle-plsql-"));
  try {
    const files  = prepare(path.resolve(folder), work);
    const record = await parse(work, files);
    const report = await gradePlSql(path.join(work, "files"), record);
    if (args.includes("--json")) { console.log(JSON.stringify(report, null, 2)); return; }
    const lines = [
      `SQL reader on PL/SQL against the ANTLR grammar at grammars-v4 ${GRAMMAR_COMMIT.slice(0, 8)}`,
      `Files: ${report.files.read} read, ${report.files.graded} graded, ${report.files.refused.length} the grammar refuses`,
      "Objects (the reader has symbols for procedures, functions, views and tables only):",
      ...Object.entries(report.objects.kinds).sort().map(([kind, bucket]) => `  ${kind.padEnd(10)} ${bucket.expected} created, ${bucket.found} found, ${bucket.linesRight} at the right line`),
      `  inside packages and type bodies: ${Object.entries(report.objects.members).sort().map(([kind, count]) => `${kind} ${count}`).join(", ")}`,
      `  invented: ${report.objects.invented.length}`,
      `Dependency lines: ${report.dependency.expected} expected, ${report.dependency.right} right, ${report.dependency.missing.length} missing, ${report.dependency.invented.length} invented`,
      ...Object.entries(report.dependency.byHow).sort().map(([how, bucket]) => `  by ${how.padEnd(12)} ${bucket.right} of ${bucket.expected}`),
      `Not graded: ${Object.entries(report.ungraded).sort().map(([how, count]) => `${how} ${count}`).join(", ")}`,
      `Names kept today that an object of a kind with no symbol would link: ${Object.entries(report.wouldResolve).sort().map(([kind, count]) => `${kind} ${count}`).join(", ") || "none"}`
    ];
    if (args.includes("--detail")) {
      for (const [title, items] of [["Refused", report.files.refused], ["Objects missing", report.objects.missing], ["Objects invented", report.objects.invented], ["Dependency lines missing", report.dependency.missing], ["Dependency lines invented", report.dependency.invented]] as const) {
        if (items.length > 0) lines.push("", `${title} (${items.length}):`, ...items.map((item) => `  ${item}`));
      }
    }
    console.log(lines.join("\n"));
  } finally {
    fs.rmSync(work, { recursive: true, force: true });
  }
}

if (require.main === module) {
  main().catch((error: unknown) => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exit(1);
  });
}
